-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Parte 1 de 7. Requiere 01_esquema.sql (columnas profile, skills y
-- mindscapes de characters) y 04_personajes_zzz.sql.
--
-- Datos de los agentes de Zenless Zone Zero sacados de HoYoWiki, la wiki oficial de
-- HoYoverse, con los textos oficiales en espanol:
--   profile     -> sexo, afiliacion, estatura, cumpleanos, actores de voz y version.
--   skills      -> las seis categorias de tecnicas (ataque normal, evasion,
--                  tecnica de apoyo, tecnica especial, tecnica en cadena y
--                  habilidad fundamental) con sus valores por nivel y los
--                  materiales para subirlas.
--   mindscapes  -> los seis niveles de Cine mental.
-- Ademas, los agentes que no tenian biografia reciben el "Diseño de personaje"
-- de la wiki (los que ya tenian una se dejan como estan).
--
-- Sin ficha en la wiki todavia: zzz-roxy.
--
-- Solo actualiza agentes que ya existen; no crea ninguno. Se puede repetir.
--
-- Generado el 2026-09-15.

update public.characters as c
set profile = v.profile,
    skills = v.skills,
    mindscapes = v.mindscapes,
    biography_es = coalesce(c.biography_es, v.biography),
    biography_source_es = case when c.biography_es is null and v.biography is not null then v.source else c.biography_source_es end
from (
  values
  ('zzz-claret', '[{"campo":"Versión de lanzamiento","valor":"3.2"},{"campo":"Género","valor":"Femenino"},{"campo":"Afiliación","valor":"Taller Flint"},{"campo":"Estatura","valor":"166 cm"},{"campo":"Cumpleaños","valor":"23 de julio"},{"campo":"Amplificador exclusivo","valor":"Sed escarlata"},{"campo":"Afiliación común","valor":"Roxy Ifrita Pryce"},{"campo":"Equipamiento","valor":"(Próximamente)"},{"campo":"Entradas relacionadas","valor":"Arca de médula ósea"},{"campo":"VA (CN)","valor":"Liǔ Zhīxiāo (柳知萧)"},{"campo":"VA (JP)","valor":"Ueda Kana (植田 佳奈)"},{"campo":"VA (KO)","valor":"Cassandra Lee Morris"},{"campo":"VA (EN)","valor":"Lee I-ro (이이로)"}]'::jsonb, '{"categorias":[{"categoria":"Ataque normal","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/08/26/7c4749265d45177f16044c76d9315db0_7689331585667217268.png","tecnicas":[{"nombre":"Ataque normal: Cuatro formas de forja sangrienta","descripcion":"Pulsa para usarlo.\nEjecuta hasta cuatro martillazos hacia delante, lo que inflige daño eléctrico."},{"nombre":"Ataque normal: Pacto de sangre - Forja estelar","descripcion":"Durante el estado de epitafio escarlata, pulsa para usarlo.\nUsa el hacha de sangre para ejecutar hasta tres cortes hacia delante, lo que inflige daño eléctrico.\nAl ejecutar el segundo movimiento de ataque de la habilidad, Claret salta hacia atrás y lanza el hacha de sangre. Mientras retrocede, Claret puede activar una evasión perfecta.\nAl ejecutar el tercer movimiento de ataque de la habilidad, Claret ejecuta cortes continuos, salta y golpea con fuerza hacia abajo.\nDurante los cortes continuos, su nivel de resistencia a interrupción aumenta y el daño recibido se reduce en un 40 %. Pulsa repetidamente o mantén pulsado para extender la duración de los cortes continuos. Al dejar de pulsar o soltar , Claret salta y golpea con fuerza hacia abajo. Durante el salto, puede activar una evasión perfecta. Tras activar con éxito una evasión perfecta, pulsa o mantén pulsado para enlazar el tercer movimiento del ataque normal: Pacto de sangre - Forja estelar.\nDurante la ejecución no sale del estado de epitafio escarlata."},{"nombre":"Ataque normal: Pacto de sangre - Hacha subyugante","descripcion":"Durante el estado de epitafio escarlata, tras ejecutar la técnica especial: Pacto de sangre - Corte de oro y hierro o la técnica especial: Pacto de sangre - Asalto de sangre sepulcral y provocar mutilación, pulsa o mantén pulsado para usarlo.\nUsa el hacha de sangre para girar, salta y golpea con fuerza hacia abajo. Después, ejecuta un corte contra el enemigo objetivo, lo que inflige daño eléctrico. Durante el salto, puede activar una evasión perfecta.\nTras la ejecución de la habilidad, pulsa o mantén pulsado para enlazar el tercer movimiento del ataque normal: Pacto de sangre - Forja estelar.\nDurante la ejecución no sale del estado de epitafio escarlata."}],"atributos":[{"clave":"Ataque normal: Cuatro formas de forja sangrienta","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de daño de 1.er golpe","valores":["54.4%","59.4%","64.4%","69.4%","74.4%","79.4%","84.4%","89.4%","94.4%","99.4%","104.4%","109.4%","114.4%","119.4%","124.4%","129.4%"]},{"clave":"Multiplicador de daño de 2.º golpe","valores":["67.2%","73.4%","79.6%","85.8%","92.0%","98.2%","104.4%","110.6%","116.8%","123.0%","129.2%","135.4%","141.6%","147.8%","154.0%","160.2%"]},{"clave":"Multiplicador de daño de 1.er golpe","valores":["95.2%","103.9%","112.6%","121.3%","130.0%","138.7%","147.4%","156.1%","164.8%","173.5%","182.2%","190.9%","199.6%","208.3%","217.0%","225.7%"]},{"clave":"Multiplicador de daño de 2.º golpe","valores":["289.5%","315.9%","342.3%","368.7%","395.1%","421.5%","447.9%","474.3%","500.7%","527.1%","553.5%","579.9%","606.3%","632.7%","659.1%","685.5%"]},{"clave":"Multiplicador de Aturdimiento de 1.er golpe","v