rse.com/event-ugc-hoyowiki/2026/06/17/19629685/dfbd2d0e44e5167b318ce5f5d21d45f8_693380662006691398.png","tecnicas":[{"nombre":"Apoyo rápido: Guardia del ocaso","descripcion":"Pulsa para usarlo cuando el personaje activo es lanzado por los aires.\nEjecuta varios ataques consecutivos contra el objetivo, lo que inflige daño etéreo.\nTras la ejecución de la habilidad, si la cantidad de Prominencia solar es igual o superior a 30 ptos., mantén pulsado para enlazar directamente el tercer movimiento del ataque normal: Luz celestial.\nDurante la ejecución de la habilidad, el personaje se vuelve invulnerable."},{"nombre":"Ataque sucesivo: Regreso a la luz","descripcion":"Pulsa para usarlo cuando el personaje en el campo de batalla esté a punto de recibir un ataque.\nBloquea el ataque enemigo, lo que provoca una gran cantidad de Aturdimiento.\nDurante la ejecución de la habilidad, el personaje se vuelve invulnerable."},{"nombre":"Apoyo defensivo: Behemot férreo","descripcion":"Tras ejecutar un apoyo defensivo, pulsa para usarlo.\nEjecuta un embate hacia delante, lo que inflige daño etéreo.\nTras la ejecución de la habilidad, si la cantidad de Prominencia solar es igual o superior a 30 ptos., mantén pulsado para enlazar directamente el tercer movimiento del ataque normal: Luz celestial.\nDurante la ejecución de la habilidad, el personaje se vuelve invulnerable."}],"atributos":[{"clave":"Apoyo rápido: Guardia del ocaso","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de daño","valores":["41.2%","45%","48.8%","52.6%","56.4%","60.2%","64%","67.8%","71.6%","75.4%","79.2%","83%","86.8%","90.6%","94.4%","98.2%"]},{"clave":"Multiplicador de Aturdimiento","valores":["34.9%","36.5%","38.1%","39.7%","41.3%","42.9%","44.5%","46.1%","47.7%","49.3%","50.9%","52.5%","54.1%","55.7%","57.3%","58.9%"]},{"clave":"","valores":["","","","","","